/* Framework-neutral API client. Configure through config.js or window.MATANHO_CONFIG. */
(()=>{
  'use strict';
  const defaults={
    API_BASE_URL:'/api/v1',
    AUTH_MODE:'cookie',
    CSRF_COOKIE:'XSRF-TOKEN',
    CSRF_HEADER:'X-XSRF-TOKEN',
    REQUEST_TIMEOUT_MS:30000,
    MOCK_MODE:true
  };
  const config=Object.freeze({...defaults,...(window.MATANHO_CONFIG||{})});
  function cookie(name){
    return document.cookie.split('; ').find(v=>v.startsWith(`${name}=`))?.split('=').slice(1).join('=')||'';
  }
  async function request(path,options={}){
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(),options.timeout||config.REQUEST_TIMEOUT_MS);
    const method=(options.method||'GET').toUpperCase();
    const headers=new Headers(options.headers||{});
    if(options.body && !(options.body instanceof FormData) && !headers.has('Content-Type')) headers.set('Content-Type','application/json');
    if(config.AUTH_MODE==='token' && config.ACCESS_TOKEN) headers.set('Authorization',`Bearer ${config.ACCESS_TOKEN}`);
    if(!['GET','HEAD','OPTIONS'].includes(method)){
      const token=cookie(config.CSRF_COOKIE);
      if(token) headers.set(config.CSRF_HEADER,decodeURIComponent(token));
    }
    try{
      const response=await fetch(`${config.API_BASE_URL.replace(/\/$/,'')}/${String(path).replace(/^\//,'')}`,{
        ...options,method,headers,credentials:config.AUTH_MODE==='cookie'?'include':options.credentials,signal:controller.signal,
        body:options.body && !(options.body instanceof FormData) && typeof options.body!=='string'?JSON.stringify(options.body):options.body
      });
      const type=response.headers.get('content-type')||'';
      const data=type.includes('application/json')?await response.json():await response.text();
      if(!response.ok){const error=new Error(data?.message||`Request failed with ${response.status}`);error.status=response.status;error.data=data;throw error;}
      return data;
    }finally{clearTimeout(timeout);}
  }
  window.MatanhoApiClient=Object.freeze({name:'fetch',config,request,get:path=>request(path),post:(path,body)=>request(path,{method:'POST',body}),put:(path,body)=>request(path,{method:'PUT',body}),patch:(path,body)=>request(path,{method:'PATCH',body}),delete:path=>request(path,{method:'DELETE'})});
})();





