  function editDocumentV5(id, report=false){
    const doc = report ? getReport(id) : getDoc(id);
    openWideModal(`Edit ${doc.name}`,'Edit the content, metadata, access controls and reusable letterhead. Changes are versioned.',
      `<div class="document-workbench">${editorSidePanel(doc,report)}${documentPaperV5(doc,true,report)}</div>`,
      actionButton('Preview','preview-editor-document',doc.id,'','eye')+actionButton('Save new version',report?'save-report-template-v5':'save-document-v5',doc.id,'primary','document'),'xl');
  }
  function saveEditorValues(id, report=false){
    const target = report ? (state.reports.find(x=>x.id===id)||state.reportTemplates.find(x=>x.id===id)) : (state.documents.find(x=>x.id===id)||state.documentTemplates.find(x=>x.id===id));
    if(target){
      target.name=$('#editDocName')?.value||target.name;
      target.type=$('#editDocType')?.value||target.type;
      target.version=$('#editDocVersion')?.value||target.version||'v1.0';
      target.owner=$('#editDocOwner')?.value||target.owner;
      target.status=$('#editDocStatus')?.value||target.status;
      target.content=$('#docEditable')?.innerHTML||target.content;
      target.date='01 Aug 2026';
    }
    state.letterhead.company=$('#editLhCompany')?.value||state.letterhead.company;
    state.letterhead.division=$('#editLhDivision')?.value||state.letterhead.division;
    state.letterhead.address=$('#editLhAddress')?.value||state.letterhead.address;
    state.letterhead.contact=$('#editLhContact')?.value||state.letterhead.contact;
    state.letterhead.registration=$('#editLhRegistration')?.value||state.letterhead.registration;
    state.letterhead.color=$('#editLhColor')?.value||state.letterhead.color;
    state.letterhead.showLogo=$('#editLhLogo')?.value!=='no';
    state.letterhead.footer=$('#editLhFooter')?.value||state.letterhead.footer;
    return target||getDoc(id);
  }

  const v4LineChart = lineChart;
  lineChart = function(id){
    const series = {
      'spend-trend':[42,48,46,56,61,66,64,72,78,75,84,92],
      'invoice-match':[61,66,70,73,71,78,80,82,86,89,91,94],
      'report-consumption':[24,32,29,45,51,49,63,68,74,72,86,93],
      'analytics-detail':[38,44,52,49,61,65,69,76,73,82,88,95]
    }[id] || [32,39,43,48,52,58,63,67,72,78,84,91];
    const actual = series.map((v,i)=>Math.max(18,v-(8-(i%3)*2)));
    const x=i=>58+i*(642/11), y=v=>252-(v/100)*205;
    const path=arr=>arr.map((v,i)=>`${i?'L':'M'} ${x(i).toFixed(1)} ${y(v).toFixed(1)}`).join(' ');
    return `<div class="chart chart-click" data-chart="${esc(id)}"><svg viewBox="0 0 740 300" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Interactive trend chart"><defs><linearGradient id="area-${esc(id)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6657d9" stop-opacity=".22"/><stop offset="1" stop-color="#6657d9" stop-opacity="0"/></linearGradient></defs><g>${[45,95,145,195,245].map(v=>`<line class="gridline" x1="58" x2="700" y1="${v}" y2="${v}"/>`).join('')}<line class="axis" x1="58" y1="252" x2="700" y2="252"/><line class="axis" x1="58" y1="38" x2="58" y2="252"/>${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].map((m,i)=>`<text x="${x(i)-8}" y="276">${m}</text>`).join('')}<text x="12" y="252">0</text><text x="9" y="201">25</text><text x="9" y="151">50</text><text x="9" y="101">75</text><text x="4" y="50">100</text><path d="${path(series)} L 700 252 L 58 252 Z" fill="url(#area-${esc(id)})"/><path d="${path(series)}" class="line"/><path d="${path(actual)}" class="line2"/>${series.map((v,i)=>`<circle class="point" data-action="chart-point-v5" data-id="${esc(id)}" data-label="${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]}" cx="${x(i)}" cy="${y(v)}" r="4.5"><title>${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i]}: ${v}</title></circle>`).join('')}</g></svg></div>`;
  };
  bars = function(items,id){return `<div class="bars" data-chart="${esc(id)}">${items.map(([l,v],index)=>`<div class="bar-row" data-action="chart-drill-v5" data-id="${esc(id)}" data-label="${esc(l)}"><span>${esc(l)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,v)}%"></div></div><b>${esc(v)}%</b></div>`).join('')}</div>`};

  function planListPageV5(){
    const planRows=state.plans.map(p=>`<tr data-action="open-plan-detail-v5" data-id="${p.id}"><td><strong class="link">${p.id}</strong><span class="row-tools-inline">${smallAction('Edit','edit-plan-v5',p.id)}${smallAction('Preview','preview-document',p.id)}</span><br><span class="muted">${esc(p.name)}</span></td><td>${esc(p.entity)}</td><td class="money">${money(p.budget)}</td><td class="money">${money(p.committed)}</td><td><div class="progress"><span style="width:${Math.min(100,p.committed/p.budget*100)}%"></span></div></td><td>${esc(p.version)}</td><td>${status(p.status)}</td><td>${smallAction('Open','open-plan-detail-v5',p.id,'arrow')}</td></tr>`);
    const itemRows=state.planItems.map(i=>`<tr data-record="plan-item" data-id="${i.id}"><td><strong class="link">${i.id}</strong><span class="row-tools-inline">${smallAction('Edit','edit-record-v5',i.id)}</span></td><td>${esc(i.description)}</td><td>${esc(i.entity)}</td><td>${esc(i.category)}</td><td>${esc(i.quarter)}</td><td>${esc(i.method)}</td><td class="money">${money(i.budget)}</td><td>${status(i.status)}</td></tr>`);
    return `<div class="page">${pageHead('Strategy and budget','Annual Procurement Planning','Create granular entity plans, consolidate subsidiary and investee submissions, validate budgets and route the complete plan for approval.',actionButton('Create plan','create-plan-v5','','primary','plus')+actionButton('Add plan item','add-plan-item','','','plus')+actionButton('Submit plan & budget','submit-plan')+actionButton('Import prior year','import-plan'))}${filterBar()}
      <div class="grid kpis">${kpi('Consolidated budget',money(8240000),'7 entities included','plan')}${kpi('Submitted plans','6 of 7','One entity outstanding','approve')}${kpi('Budget coverage','93.6%','Funded planned requirements','report')}${kpi('Strategic tenders','12','Above delegated thresholds','tender')}${kpi('Plan amendments','4','Version history retained','document')}${kpi('Unfunded exposure',money(528000),'Requires budget decision','account')}</div>
      ${card('Procurement plans','Open a plan to edit its assumptions, requirements, funding, approvals and controlled documents.',`<div class="table-tools"><input placeholder="Search plans"><select><option>All entities</option>${entities.slice(1).map(x=>`<option>${x[1]}</option>`).join('')}</select><select><option>All statuses</option><option>Draft</option><option>Under review</option><option>Approved</option></select></div>${table(['Plan','Entity','Budget','Committed','Execution','Version','Status',''],planRows)}`)}
      <div style="height:14px"></div>${card('Plan requirement register','Approved requirements can be converted to requisitions, RFQs or tenders.',table(['Item','Requirement','Entity','Category','Quarter','Method','Budget','Status'],itemRows))}</div>`;
  }
  function planDetailPageV5(id){
    const p=state.plans.find(x=>x.id===id)||state.plans[0];
    const items=state.planItems.filter((x,i)=>x.entity===p.entity||p.entity==='Group Consolidated'||i<3);
    const rows=items.map(i=>`<tr><td><strong>${i.id}</strong></td><td>${esc(i.description)}</td><td>${esc(i.category)}</td><td>${esc(i.quarter)}</td><td>${esc(i.method)}</td><td>${money(i.budget)}</td><td>${status(i.status)}</td><td>${smallAction('Edit','edit-record-v5',i.id)}</td></tr>`);
    return `<div class="page"><div class="breadcrumbs"><button data-action="back-plan-list-v5">Annual Procurement Plans</button><i>›</i><span>${p.id}</span><i>›</i><strong>${esc(p.name)}</strong></div>
      ${pageHead('Plan workspace',p.name,`${p.entity} · ${p.version} · owned by ${p.owner}`,actionButton('Edit plan','edit-plan-v5',p.id,'primary','document')+actionButton('Add requirement','add-plan-item','','','plus')+actionButton('Preview controlled plan','preview-document',p.id,'','eye')+actionButton('Submit','submit-plan'))}
      <div class="workflow-strip"><div class="workflow-step done"><strong>1. Demand collection</strong><span>Completed by 7 entities</span></div><div class="workflow-step done"><strong>2. Budget validation</strong><span>93.6% funded</span></div><div class="workflow-step current"><strong>3. Procurement review</strong><span>4 items need action</span></div><div class="workflow-step"><strong>4. CFO review</strong><span>Pending</span></div><div class="workflow-step"><strong>5. Committee approval</strong><span>Pending</span></div><div class="workflow-step"><strong>6. Baseline issued</strong><span>Not started</span></div></div>
      <div class="grid kpis">${kpi('Plan budget',money(p.budget),'Approved ceiling','plan')}${kpi('Committed',money(p.committed),'Current commitments','order')}${kpi('Available',money(p.budget-p.committed),'Uncommitted capacity','account')}${kpi('Requirements',items.length,'Current plan lines','requisition')}${kpi('Funding gaps','2','Budget decision required','audit')}${kpi('Approval SLA','2.4 days','Current workflow estimate','approve')}</div>
      <div class="grid two" style="margin-bottom:14px">${card('Execution forecast','Monthly planned, committed and actual spend',`<div class="card-body">${lineChart('plan-execution')}</div>`)}${card('Plan governance','Owners, funding and approval evidence',`<div class="card-body list"><div class="list-row" data-action="edit-plan-v5" data-id="${p.id}"><div class="list-main"><strong>Planning assumptions</strong><span>Demand, inflation, currency and implementation dependencies</span></div>${icon('arrow')}</div><div class="list-row" data-action="preview-document" data-id="${p.id}"><div class="list-main"><strong>Controlled plan document</strong><span>Editable letterhead, version and approval record</span></div>${icon('arrow')}</div><div class="list-row" data-page="approvals"><div class="list-main"><strong>Approval workflow</strong><span>Entity, Group Procurement, CFO and committee</span></div>${icon('arrow')}</div></div>`)}</div>
      ${card('Plan requirements','Edit, classify, fund or convert each approved item.',table(['Item','Requirement','Category','Quarter','Sourcing method','Budget','Status',''],rows))}</div>`;
  }
  function planPageV5(){return state.planDetail?planDetailPageV5(state.planDetail):planListPageV5()}

