  function taxRuleV6(vendorOrName){
    const vendor=typeof vendorOrName==='string'?state.vendors.find(v=>v.name===vendorOrName):vendorOrName;
    if(!vendor) return {level:'warning',label:'Vendor not selected',rule:'Select a vendor to calculate the purchase tax rule.',withholding:0,status:'Pending'};
    if(vendor.country!=='Zimbabwe') return {level:'warning',label:'Non-resident tax review',rule:'Route the purchase to Finance for import VAT and non-resident tax review before contract or PO approval.',withholding:0,status:'Specialist review'};
    const remaining=vendor.taxExpiry?daysUntilV6(vendor.taxExpiry):-999;
    if(!vendor.taxExpiry || remaining<0) return {level:'blocked',label:'30% withholding configured',rule:'Tax clearance is missing or expired. The PO and purchase contract must display the configured 30% withholding clause and payment remains subject to compliance review.',withholding:30,status:remaining<0?'Expired':'Missing'};
    if(remaining<=60) return {level:'warning',label:'Tax clearance expiring',rule:`Tax clearance expires in ${remaining} days. Purchasing may continue under current approval, while automated reminders are sent to the vendor and internal owner.`,withholding:0,status:'Expiring'};
    return {level:'',label:'Standard compliant treatment',rule:'Approved tax clearance is current. Apply standard VAT and withholding controls configured for the purchase and invoice.',withholding:0,status:'Valid'};
  }
  function vendorComplianceCountV6(statusName){ return state.vendors.reduce((n,v)=>n+v.complianceDocs.filter(d=>d.status===statusName).length,0); }
  function vendorStatusChipV6(v){
    const rule=taxRuleV6(v); return `<span class="vendor-doc-chip-v6 ${rule.status==='Valid'?'valid':rule.status==='Expiring'?'expiring':'missing'}">${esc(rule.status)}</span>`;
  }
  function taxRuleCardV6(vendor){
    const rule=taxRuleV6(vendor); return `<div class="tax-rule-v6 ${rule.level}"><h4>${esc(rule.label)}</h4><p>${esc(rule.rule)}</p><p><strong>Purchase control:</strong> ${rule.withholding?`${rule.withholding}% withholding shown on PO, contract and payment review`:'Standard configured treatment'}</p></div>`;
  }
  function openV6Modal(title,sub,body,foot='',size='xl'){
    openModal(title,sub,body,foot);
    const modal=document.querySelector('#modalLayer .modal');
    if(modal){ modal.classList.remove('modal-wide','modal-xl','modal-tall','modal-v6-wide','modal-v6-xl','modal-v6-full'); modal.classList.add(size==='full'?'modal-v6-full':size==='wide'?'modal-v6-wide':'modal-v6-xl'); }
  }
  function installProfileV6(){
    const avatar=document.querySelector('.avatar');
    if(avatar){ avatar.classList.add('avatar-photo'); avatar.innerHTML=`<img src="${V6_AVATAR}" alt="Nyasha Moyo profile">`; avatar.dataset.action='open-profile-v6'; avatar.setAttribute('aria-label','Open Nyasha Moyo profile'); }
    const name=document.querySelector('.user-name');
    if(name){ name.dataset.action='open-profile-v6'; name.innerHTML='<strong>Nyasha Moyo</strong><br><span style="font-size:11px;color:var(--muted)">Group Procurement Lead</span>'; }
  }

  function docByIdV6(id){
    return state.documents.find(d=>d.id===id)||state.documentTemplates.find(d=>d.id===id)||state.reports.find(d=>d.id===id)||state.reportTemplates.find(d=>d.id===id)||{id:id||'DOC-DRAFT',name:'Controlled Procurement Document',type:'Controlled document',version:'v1.0',status:'Draft',owner:'Group Procurement',content:'<h1>Controlled Procurement Document</h1><p>Edit the document content before approval and issue.</p>'};
  }
  function letterheadV6(editable=false){
    const lh=state.letterhead;
    const attr=id=>editable?`id="${id}" contenteditable="true" spellcheck="true"`:'';
    return `<header class="letterhead-v6" style="--lh-color:${esc(lh.color||'#5b5f9e')}"><div><img src="${LOGO_DATA}" alt="Matanho"><h1 ${attr('v6LhCompany')}>${esc(lh.company)}</h1><p ${attr('v6LhDivision')}>${esc(lh.division)}</p><p ${attr('v6LhAddress')}>${esc(lh.address)}</p></div><div class="meta"><div ${attr('v6LhContact')}>${esc(lh.contact)}</div><div ${attr('v6LhRegistration')}>${esc(lh.registration)}</div><div style="margin-top:9px;color:${esc(lh.color||'#5b5f9e')};font-weight:800">CONTROLLED COPY</div></div></header>`;
  }
  function paperV6(doc,editable=false){
    const bodyAttr=editable?'id="v6EditableBody" contenteditable="true" spellcheck="true"':'';
    return `<div class="preview-stage"><article class="paper-v6">${letterheadV6(editable)}<div class="doc-body-v6" ${bodyAttr}>${doc.content||''}</div><footer class="doc-footer-v6"><span ${editable?'id="v6LhFooter" contenteditable="true"':''}>${esc(state.letterhead.footer)}</span><span>${esc(doc.id||'DRAFT')} | ${esc(doc.version||'v1.0')}</span></footer></article></div>`;
  }
  function previewDocV6(id){
    const doc=docByIdV6(id);
    openV6Modal(doc.name,`${doc.id} | ${doc.version||'v1.0'} | ${doc.status||'Controlled'}`,paperV6(doc,false),
      actionV6('Edit','edit-document',doc.id,'','document')+actionV6('Upload version','upload-version',doc.id,'','plus')+actionV6('Send / request response','send-document',doc.id,'','mail')+actionV6('eSign','esign-new-v6',doc.id,'','signature')+actionV6('PDF','download-document-v5',doc.id,'','download')+actionV6('Excel','download-document-xls',doc.id,'','download')+actionV6('CSV','download-document-csv',doc.id,'','download'),'full');
  }
  function editDocV6(id,report=false){
    const doc=docByIdV6(id);
    const body=`<div class="doc-editor-v6"><div class="preview-stage">${paperV6(doc,true).replace('<div class="preview-stage">','').replace(/<\/div>$/,'')}</div><aside class="editor-side"><h3 style="margin-top:0">Document settings</h3><div class="form-grid">${formField('Title',`<input id="v6DocName" value="${esc(doc.name)}">`,'full')}${formField('Version',`<input id="v6DocVersion" value="${esc(doc.version||'v1.0')}">`)}${formField('Status',`<select id="v6DocStatus"><option>Draft</option><option ${doc.status==='Published'?'selected':''}>Published</option><option ${doc.status==='Approved'?'selected':''}>Approved</option><option>Under review</option></select>`)}${formField('Owner',`<input id="v6DocOwner" value="${esc(doc.owner||'Group Procurement')}">`,'full')}${formField('Company',`<input id="v6LhCompanyInput" value="${esc(state.letterhead.company)}">`,'full')}${formField('Division',`<input id="v6LhDivisionInput" value="${esc(state.letterhead.division)}">`,'full')}${formField('Address',`<textarea id="v6LhAddressInput">${esc(state.letterhead.address)}</textarea>`,'full')}${formField('Contact',`<input id="v6LhContactInput" value="${esc(state.letterhead.contact)}">`,'full')}${formField('Registration / tax',`<input id="v6LhRegistrationInput" value="${esc(state.letterhead.registration)}">`,'full')}${formField('Accent colour',`<input id="v6LhColorInput" type="color" value="${esc(state.letterhead.color||'#5b5f9e')}">`)}${formField('Read access','<select><option>Procurement, approvers and document owners</option><option>Named users only</option><option>All authorised entity users</option></select>')}${formField('Write access','<select><option>Owner and designated editors</option><option>Procurement administrators</option></select>')}${formField('Change note','<textarea id="v6DocChangeNote">Updated controlled template content and letterhead.</textarea>','full')}</div></aside></div>`;
    openV6Modal(`Edit ${doc.name}`,`${doc.id} | Changes create a controlled version`,body,actionV6('Preview','preview-editor-v6',doc.id,'','eye')+actionV6('Save version','save-document-v6',doc.id,'primary','document'),'full');
  }
  function saveDocEditorV6(id){
    const doc=docByIdV6(id);
    doc.name=$('#v6DocName')?.value||doc.name; doc.version=$('#v6DocVersion')?.value||doc.version; doc.status=$('#v6DocStatus')?.value||doc.status; doc.owner=$('#v6DocOwner')?.value||doc.owner; doc.content=$('#v6EditableBody')?.innerHTML||doc.content;
    state.letterhead.company=$('#v6LhCompanyInput')?.value||$('#v6LhCompany')?.textContent||state.letterhead.company;
    state.letterhead.division=$('#v6LhDivisionInput')?.value||$('#v6LhDivision')?.textContent||state.letterhead.division;
    state.letterhead.address=$('#v6LhAddressInput')?.value||$('#v6LhAddress')?.textContent||state.letterhead.address;
    state.letterhead.contact=$('#v6LhContactInput')?.value||$('#v6LhContact')?.textContent||state.letterhead.contact;
    state.letterhead.registration=$('#v6LhRegistrationInput')?.value||$('#v6LhRegistration')?.textContent||state.letterhead.registration;
    state.letterhead.color=$('#v6LhColorInput')?.value||state.letterhead.color;
    state.letterhead.footer=$('#v6LhFooter')?.textContent||state.letterhead.footer;
    return doc;
  }

  function planActualsChartV6(rows){
    const max=Math.max(...rows.map(r=>r.planAmount),1);
    return `<div class="plan-actual-chart-v6">${rows.map(r=>`<button class="plan-actual-row-v6" data-action="open-plan-actual-v6" data-id="${esc(r.id)}" style="border:0;background:transparent;text-align:left;padding:0"><span><strong>${esc(r.department)}</strong><small style="display:block;color:var(--muted)">${esc(r.item)}</small></span><span class="plan-actual-tracks-v6"><span class="plan-actual-track-v6 plan"><span style="width:${Math.min(100,r.planAmount/max*100)}%"></span></span><span class="plan-actual-track-v6 commit"><span style="width:${Math.min(100,r.committed/max*100)}%"></span></span><span class="plan-actual-track-v6 actual"><span style="width:${Math.min(100,r.actual/max*100)}%"></span></span></span><strong>${Math.round(r.actual/r.planAmount*100)}%</strong></button>`).join('')}<div class="legend"><span><i style="background:#7b82bd"></i>Planned</span><span><i style="background:#3b82c4"></i>Committed</span><span><i style="background:#0f8f78"></i>Actual</span></div></div>`;
  }
  function planActualsPageV6(){
    const rows=state.planActualsV6;
    const planned=rows.reduce((n,r)=>n+r.planAmount,0),committed=rows.reduce((n,r)=>n+r.committed,0),actual=rows.reduce((n,r)=>n+r.actual,0),planQty=rows.reduce((n,r)=>n+r.planQty,0),actualQty=rows.reduce((n,r)=>n+r.actualQty,0);
    const lineRows=rows.map(r=>`<tr data-action="open-plan-actual-v6" data-id="${esc(r.id)}"><td><strong class="link">${esc(r.id)}</strong></td><td><strong>${esc(r.item)}</strong><br><span class="muted">${esc(r.entity)}</span></td><td>${esc(r.department)}</td><td>${r.planQty} ${esc(r.unit)}</td><td>${r.orderedQty} ${esc(r.unit)}</td><td>${r.actualQty} ${esc(r.unit)}</td><td>${money(r.planAmount)}</td><td>${money(r.committed)}</td><td>${money(r.actual)}</td><td>${money(r.planAmount-r.actual)}</td><td>${status(r.status)}</td><td>${smallAction('Drill down','open-plan-actual-v6',r.id)}</td></tr>`);
    const budgetRows=state.departmentBudgetsV6.map(d=>{const used=d.actual+d.committed;const pct=Math.min(100,used/d.budget*100);return `<tr><td><strong>${esc(d.department)}</strong></td><td>${money(d.budget)}</td><td>${money(d.planned)}</td><td>${money(d.committed)}</td><td>${money(d.actual)}</td><td>${money(d.budget-d.committed-d.actual)}</td><td><div class="budget-meter-v6"><span class="actual" style="width:${d.actual/d.budget*100}%"></span><span class="commit" style="width:${d.committed/d.budget*100}%"></span><span class="remaining" style="width:${Math.max(0,100-pct)}%"></span></div></td><td>${smallAction('Open','open-department-budget-v6',d.department)}</td></tr>`});
    return `<div class="page"><div class="breadcrumbs"><button data-action="back-plan-v6">Annual Procurement Plan</button><i>›</i><strong>Actuals vs Plan</strong></div>${pageHead('Plan execution','Actuals vs Plan','Track every approved line by department budget, planned quantity, ordered quantity, received quantity, commitment and actual spend.',actionV6('Back to plans','back-plan-v6')+actionV6('Export detail','download-analysis','','','download')+actionV6('Create plan amendment','create-plan','','primary','plus'))}<div class="filterbar"><select><option>FY 2026</option><option>FY 2027</option></select><select><option>All departments</option>${state.departmentBudgetsV6.map(d=>`<option>${esc(d.department)}</option>`).join('')}</select><select><option>All entities</option>${entities.slice(1).map(e=>`<option>${esc(e[1])}</option>`).join('')}</select><select><option>All statuses</option><option>On plan</option><option>Behind plan</option><option>Complete</option><option>Quantity variance</option></select><button class="btn primary" data-action="apply-plan-actual-filter-v6">Apply filters</button></div><div class="grid kpis">${kpi('Approved plan',money(planned),'Current line-item baseline','plan')}${kpi('Committed',money(committed),`${Math.round(committed/planned*100)}% of plan`,'order')}${kpi('Actual spend',money(actual),`${Math.round(actual/planned*100)}% of plan`,'account')}${kpi('Quantity executed',`${actualQty} / ${planQty}`,'Across all plan units','receive')}${kpi('Remaining plan',money(planned-actual),'Before commitments','report')}${kpi('Departments at risk','2','Budget or delivery attention','audit')}</div><div class="grid two" style="margin-bottom:14px">${card('Line execution profile','Click a line to inspect requisitions, tender, PO, receipt and invoices.',`<div class="card-body">${planActualsChartV6(rows)}</div>`)}${card('Management observations','Quantity, timing and department budget signals',`<div class="card-body list"><div class="list-row" data-action="open-plan-actual-v6" data-id="PPI-0002"><div class="list-main"><strong>Solar pump programme behind quantity plan</strong><span>12 of 18 ordered; no accepted receipt recorded</span></div>${status('Attention')}</div><div class="list-row" data-action="open-plan-actual-v6" data-id="PPI-0004"><div class="list-main"><strong>Fleet tyre quantity variance</strong><span>190 of 640 received; framework remains within value</span></div>${status('Review')}</div><div class="list-row" data-action="open-department-budget-v6" data-id="Clinical Services"><div class="list-main"><strong>Clinical Services budget utilisation</strong><span>High utilisation following MRI capital purchase</span></div>${status('High')}</div></div>`)}</div>${card('Department budget execution','Budget, plan, committed and actual values with remaining capacity.',table(['Department','Budget','Planned','Committed','Actual','Remaining','Utilisation',''],budgetRows))}<div style="height:14px"></div>${card('Plan line-item execution','Granular quantity and value tracking down to the approved plan requirement.',table(['Plan item','Requirement','Department','Plan qty','Ordered qty','Actual qty','Plan value','Committed','Actual','Remaining','Status',''],lineRows))}</div>`;
  }

  const planPageV5RefV6=pages.plan;
  function planPageV6(){ return state.planViewV6==='actuals'?planActualsPageV6():planPageV5RefV6(); }

  function vendorRegisterPageV6(){
    const rows=state.vendors.map(v=>{const rule=taxRuleV6(v);const missing=v.complianceDocs.filter(d=>['Missing','Expired'].includes(d.status)).length;return `<tr><td><strong class="link">${esc(v.id)}</strong></td><td><strong>${esc(v.name)}</strong><br><span class="muted">${esc(v.country)} | ${esc(v.email)}</span></td><td>${esc(v.category)}</td><td>${esc(v.bp)}</td><td>${esc(v.currency)}</td><td>${vendorStatusChipV6(v)}<br><span class="muted">${v.taxExpiry?fmtDateV6(v.taxExpiry):'No approved expiry'}</span></td><td>${missing?status(`${missing} missing`):status('Complete')}</td><td>${v.rating} / 5</td><td>${status(v.status)}</td><td><div class="actions">${smallAction('Open','open-vendor-v6',v.id)}${smallAction('Request docs','request-vendor-docs-v6',v.id,'mail')}${smallAction('Message','message-vendor-v6',v.id,'mail')}</div></td></tr>`});
    const expiring=state.vendors.filter(v=>{const r=taxRuleV6(v);return ['Expiring','Expired','Missing'].includes(r.status)});
    const messages=state.vendorMessagesV6.slice(0,4).map(m=>`<div class="list-row" data-action="open-vendor-message-v6" data-id="${m.id}"><div class="list-main"><strong>${esc(m.vendor)} | ${esc(m.subject)}</strong><span>${esc(m.direction)} | ${esc(m.date)} | ${m.attachments.length} attachment(s)</span></div>${status(m.status)}</div>`).join('');
    return `<div class="page">${pageHead('Supplier master and communications','Vendor Registry','Register suppliers, request company and compliance records, receive vendor documents and messages, monitor tax-clearance expiry and enforce purchasing rules.',actionV6('Register vendor','register-vendor','', 'primary','plus')+actionV6('Request compliance','request-vendor-docs-v6','','','mail')+actionV6('Vendor portal','vendor-portal','','','vendor')+actionV6('Run reminders','run-compliance-reminders-v6','','','mail'))}${filterBar()}<div class="grid kpis">${kpi('Registered vendors',state.vendors.length,'Controlled master records','vendor')}${kpi('Current tax clearance',state.vendors.filter(v=>taxRuleV6(v).status==='Valid').length,'Approved ITF263 records','approve')}${kpi('Expiring / expired',expiring.length,'Automated reminders active','audit')}${kpi('Missing documents',vendorComplianceCountV6('Missing'),'Company, tax or banking evidence','document')}${kpi('Inbound messages',state.vendorMessagesV6.filter(m=>m.direction==='Inbound').length,'Vendor portal and email intake','mail')}${kpi('Pending compliance requests',state.vendorRequestsV6.filter(r=>r.status!=='Complete').length,'Tracked until approved','report')}</div><div class="grid two" style="margin-bottom:14px">${card('Compliance status','Every doughnut segment includes a visible legend and can be selected.',`<div class="card-body donut-wrap"><div class="donut chart-click" data-chart="vendor-compliance" style="background:conic-gradient(#0f8f78 0 46%,#b87518 46% 67%,#c54a58 67% 84%,#d9dde5 84% 100%)"><div class="donut-center"><strong>${state.vendors.length}</strong><span>vendors</span></div></div><div class="donut-legend-v6"><button data-action="vendor-compliance-filter-v6" data-id="Valid"><i style="background:#0f8f78"></i><span>Current</span><strong>46%</strong></button><button data-action="vendor-compliance-filter-v6" data-id="Expiring"><i style="background:#b87518"></i><span>Expiring</span><strong>21%</strong></button><button data-action="vendor-compliance-filter-v6" data-id="Expired"><i style="background:#c54a58"></i><span>Expired / missing</span><strong>17%</strong></button><button data-action="vendor-compliance-filter-v6" data-id="Review"><i style="background:#d9dde5"></i><span>Under review</span><strong>16%</strong></button></div></div>`)}${card('Vendor communication inbox','Receive messages, updated documents, clarifications and contract correspondence.',`<div class="card-body list">${messages}</div>`,smallAction('Open inbox','open-vendor-inbox-v6'))}</div><div class="compliance-grid-v6" style="margin-bottom:14px"><article class="compliance-card-v6"><span class="metric">${vendorComplianceCountV6('Valid')}</span><h4>Valid documents</h4><p>Approved statutory, company, banking and tax evidence.</p></article><article class="compliance-card-v6"><span class="metric">${vendorComplianceCountV6('Expiring')}</span><h4>Expiring soon</h4><p>Reminder schedule at 90, 60, 30 and 7 days.</p></article><article class="compliance-card-v6"><span class="metric">${vendorComplianceCountV6('Expired')}</span><h4>Expired</h4><p>Purchase and payment tax controls are displayed automatically.</p></article><article class="compliance-card-v6"><span class="metric">${state.vendorMessagesV6.reduce((n,m)=>n+m.attachments.length,0)}</span><h4>Received attachments</h4><p>Stored in the controlled Vendor Submissions folder.</p></article></div>${card('Vendor registry','Open a vendor to review profile, documents, tax rules, communications, performance and transaction history.',table(['Vendor ID','Vendor','Category','BP number','Currency','Tax clearance','Document gaps','Rating','Status','Actions'],rows))}</div>`;
  }
  function vendorDetailPageV6(v){
    const docs=v.complianceDocs.map(d=>`<tr><td><strong>${esc(d.type)}</strong></td><td>${esc(d.version)}</td><td>${esc(d.updated)}</td><td>${status(d.status)}</td><td><div class="actions">${smallAction('Preview','preview-vendor-doc-v6',`${v.id}|${d.type}`,'eye')}${smallAction('Upload replacement','vendor-upload-doc-v6',`${v.id}|${d.type}`,'plus')}${smallAction('Request update','request-vendor-docs-v6',v.id,'mail')}</div></td></tr>`);
    const msgs=state.vendorMessagesV6.filter(m=>m.vendor===v.name).map(m=>`<tr><td>${esc(m.date)}</td><td>${esc(m.direction)}</td><td><strong>${esc(m.subject)}</strong><br><span class="muted">${esc(m.body.slice(0,95))}${m.body.length>95?'...':''}</span></td><td>${m.attachments.map(a=>`<span class="vendor-doc-chip-v6 valid">${esc(a)}</span>`).join('')||'-'}</td><td>${status(m.status)}</td><td>${smallAction('Open','open-vendor-message-v6',m.id)}</td></tr>`);
    return `<div class="page"><div class="breadcrumbs"><button data-action="back-vendors-v6">Vendor Registry</button><i>›</i><strong>${esc(v.name)}</strong></div>${pageHead('Vendor profile',v.name,`${v.id} | ${v.category} | ${v.country}`,actionV6('Edit profile','edit-vendor-v6',v.id,'primary')+actionV6('Request documents','request-vendor-docs-v6',v.id,'','mail')+actionV6('Open vendor portal','vendor-portal-v6',v.id,'','vendor')+actionV6('Send message','message-vendor-v6',v.id,'','mail'))}<div class="grid kpis">${kpi('Vendor rating',`${v.rating} / 5`,'Historical delivery and quality','vendor')}${kpi('Lifetime spend',money(v.spend),'Across authorised entities','account')}${kpi('Tax clearance',taxRuleV6(v).status,v.taxExpiry?`Expires ${fmtDateV6(v.taxExpiry)}`:'No approved document','audit')}${kpi('Compliance documents',v.complianceDocs.filter(d=>d.status==='Valid').length,`${v.complianceDocs.length} tracked records`,'document')}${kpi('Open requests',state.vendorRequestsV6.filter(r=>r.vendor===v.name&&r.status!=='Complete').length,'Automated reminders active','mail')}${kpi('Messages',state.vendorMessagesV6.filter(m=>m.vendor===v.name).length,'Inbound and outbound','mail')}</div><div class="grid two" style="margin-bottom:14px">${card('Purchase tax and compliance rule','Displayed on purchase contracts, POs, invoices and payment review.',`<div class="card-body">${taxRuleCardV6(v)}<div class="actions" style="margin-top:12px">${actionV6('Send compliance reminder','send-vendor-reminder-v6',v.id,'','mail')}${actionV6('Preview PO clause','preview-tax-clause-v6',v.id,'','eye')}</div></div>`)}${card('Company profile','Editable vendor master information and controlled change history.',`<div class="card-body"><div class="form-grid"><div class="field"><label>Legal name</label><input value="${esc(v.name)}" readonly></div><div class="field"><label>Vendor ID</label><input value="${esc(v.id)}" readonly></div><div class="field"><label>BP number</label><input value="${esc(v.bp)}" readonly></div><div class="field"><label>VAT number</label><input value="${esc(v.vat)}" readonly></div><div class="field"><label>Primary contact</label><input value="${esc(v.contact)}" readonly></div><div class="field"><label>Email</label><input value="${esc(v.email)}" readonly></div></div></div>`)}</div>${card('Compliance document register','Vendors can upload current documents through the secure portal; internal reviewers approve or reject each version.',table(['Document','Version','Updated','Status','Actions'],docs))}<div style="height:14px"></div>${card('Vendor communications and received documents','Messages and files received from the vendor are retained against the vendor record and in the Document Vault.',table(['Date','Direction','Subject','Attachments','Status',''],msgs.length?msgs:[`<tr><td colspan="6">No communication records.</td></tr>`]))}</div>`;
  }
  function vendorsPageV6(){ const v=state.vendors.find(x=>x.id===state.vendorDetail); return v?vendorDetailPageV6(v):vendorRegisterPageV6(); }

  function approvalsPageV6(){
    const pending=state.approvalPromptsV6.filter(a=>a.status!=='Approved'&&a.status!=='Rejected');
    const tabbar=`<div class="settings-tabs-v5"><button class="tab ${state.approvalTabV6==='mine'?'active':''}" data-action="approval-tab-v6" data-id="mine">My approvals <span class="nav-count" style="display:inline-grid">${pending.length}</span></button><button class="tab ${state.approvalTabV6==='group'?'active':''}" data-action="approval-tab-v6" data-id="group">Group queue</button><button class="tab ${state.approvalTabV6==='esign'?'active':''}" data-action="approval-tab-v6" data-id="esign">eSignature</button><button class="tab ${state.approvalTabV6==='delegations'?'active':''}" data-action="approval-tab-v6" data-id="delegations">Delegations</button></div>`;
    let content='';
    if(state.approvalTabV6==='mine'||state.approvalTabV6==='group'){
      const list=state.approvalTabV6==='mine'?pending:state.approvalPromptsV6;
      const cards=list.slice(0,6).map(a=>`<article class="approval-prompt-v6 ${a.priority.toLowerCase()}"><div style="display:flex;justify-content:space-between;gap:8px"><span class="eyebrow">${esc(a.type)}</span>${status(a.priority)}</div><h4>${esc(a.title)}</h4><p>${esc(a.record)} | ${esc(a.entity)}</p><div class="approval-facts-v6"><div><span>Decision role</span><strong>${esc(a.role)}</strong></div><div><span>Due</span><strong>${esc(a.due)}</strong></div><div><span>Value</span><strong>${a.amount?money(a.amount):'N/A'}</strong></div><div><span>eSignature</span><strong>${a.esign?'Required':'Not required'}</strong></div></div><div class="actions">${smallAction('Review','open-approval-v6',a.id,'eye')}${smallAction('Approve','approve-prompt-v6',a.id,'approve')}${smallAction('Delegate','delegate-approval-v6',a.id)}</div></article>`).join('');
      const rows=list.map(a=>`<tr><td><strong class="link">${esc(a.id)}</strong></td><td>${esc(a.type)}</td><td><strong>${esc(a.title)}</strong><br><span class="muted">${esc(a.record)}</span></td><td>${esc(a.entity)}</td><td>${a.amount?money(a.amount):'-'}</td><td>${esc(a.role)}</td><td>${esc(a.due)}</td><td>${status(a.priority)}</td><td>${status(a.status)}</td><td><div class="actions">${smallAction('Review','open-approval-v6',a.id,'eye')}${smallAction('Approve','approve-prompt-v6',a.id)}${smallAction('Reject','reject-prompt-v6',a.id)}</div></td></tr>`);
      content=`<div class="approval-prompt-grid-v6">${cards}</div><div style="height:14px"></div>${card('Approval queue','Every prompt includes the record, supporting documents, authority check, segregation-of-duties result and eSignature requirement.',table(['Approval','Type','Record','Entity','Value','Role','Due','Priority','Status','Actions'],rows))}`;
    }
    if(state.approvalTabV6==='esign'){
      const envelopes=state.signatureEnvelopesV6.map(e=>`<tr><td><strong class="link">${esc(e.id)}</strong></td><td>${esc(e.document)}</td><td>${esc(e.order)}</td><td>${e.signers.map(s=>`${esc(s.role)}: ${esc(s.status)}`).join('<br>')}</td><td>${esc(e.due)}</td><td>${status(e.status)}</td><td><div class="actions">${smallAction('Open','esign-open-v6',e.id,'eye')}${smallAction('Sign','esign-sign-v6',e.id,'signature')}${smallAction('Remind','esign-remind-v6',e.id,'mail')}</div></td></tr>`);
      content=`<div class="notice" style="margin-bottom:14px"><span class="kpi-icon">${icon('signature')}</span><div><strong>Matanho eSignature</strong><p>Ordered or parallel signing, OTP authentication, reminders, consent evidence, document hash and final audit certificate.</p></div></div>${card('Signature envelopes','Open an envelope to review signers, signing order and audit events.',table(['Envelope','Document','Order','Signers','Due','Status','Actions'],envelopes),actionV6('New envelope','esign-new-v6','','primary','signature'))}`;
    }
    if(state.approvalTabV6==='delegations'){
      content=`<div class="dense-form"><section class="form-section"><div class="form-section-head"><div><h3>Approval delegation</h3><p>Delegations are time-bound, scoped, approved and audited. The delegator remains visible in the decision record.</p></div>${actionV6('Create delegation','create-delegation-v6','','primary','plus')}</div>${table(['Delegator','Delegate','Role','Scope','From','To','Status',''],[`<tr><td>Tinashe Chaka</td><td>Rudo Ndlovu</td><td>CFO backup</td><td>Invoices up to $100,000</td><td>05 Aug 2026</td><td>12 Aug 2026</td><td>${status('Scheduled')}</td><td>${smallAction('Edit','create-delegation-v6','DEL-001')}</td></tr>`,`<tr><td>Panashe Mlambo</td><td>Tariro Moyo</td><td>Department Approver</td><td>Kariba Agro requisitions</td><td>01 Aug 2026</td><td>03 Aug 2026</td><td>${status('Active')}</td><td>${smallAction('Revoke','revoke-delegation-v6','DEL-002')}</td></tr>`])}</section></div>`;
    }
    return `<div class="page">${pageHead('Decision workflow','Approval Centre','Approvers receive prompts in notifications and this dedicated workspace. RBAC, delegated authority, SoD and eSignature are validated before every decision.',actionV6('Approval matrix','approval-matrix')+actionV6('New eSignature','esign-new-v6','','primary','signature'))}<div class="grid kpis">${kpi('Awaiting me',pending.length,'Across plan, award, PO, vendor and contract','approve')}${kpi('Due today',pending.filter(a=>/Today/i.test(a.due)).length,'Executive action required','audit')}${kpi('CEO prompts',pending.filter(a=>a.role==='CEO').length,'Strategic awards and contracts','vendor')}${kpi('CFO prompts',pending.filter(a=>a.role==='CFO').length,'Budget, PO and payment authority','account')}${kpi('eSign pending',state.signatureEnvelopesV6.filter(e=>/Awaiting/i.test(e.status)).length,'Authenticated signatures','signature')}${kpi('SoD checks','100%','Validated before decision','settings')}</div><section class="card">${tabbar}<div class="settings-pane">${content}</div></section></div>`;
  }

  function settingsPageV6(){
    const tabs=[['roles','Roles and permissions'],['users','Users and assignments'],['requests','Access requests'],['approvers','Approver authority'],['sod','SoD and policies'],['integrations','Integrations']];
    const tabbar=`<div class="settings-tabs-v5">${tabs.map(([id,label])=>`<button class="tab ${state.settingsTabV6===id?'active':''}" data-action="settings-tab-v6" data-id="${id}">${label}${id==='requests'?` <span class="nav-count" style="display:inline-grid">${state.accessRequests.filter(r=>r.status==='Pending').length}</span>`:''}</button>`).join('')}</div>`;
    let content='';
    if(state.settingsTabV6==='roles'){
      const roleCards=state.rbacV5.map((r,ri)=>`<article class="rbac-role-card-v6"><div style="display:flex;justify-content:space-between;gap:8px"><div><h4>${esc(r.name)}</h4><p>${esc(r.scope)} | ${r.users} user(s)</p></div>${status(r.classification||'Active')}</div><div class="rbac-badges-v6"><span class="rbac-badge-v6">Limit: ${r.approvalLimit===Infinity?'Unlimited':money(r.approvalLimit||0)}</span><span class="rbac-badge-v6">${r.canDelegate?'Can delegate':'No delegation'}</span><span class="rbac-badge-v6">MFA ${esc(r.mfa||'Required')}</span></div><div class="actions" style="margin-top:10px">${smallAction('Edit','edit-role-v6',String(ri))}${smallAction('Assign users','assign-role-v6',String(ri))}${smallAction('Access request','new-access-request-v5',r.name)}</div></article>`).join('');
      const rows=[];
      state.rbacV5.forEach((role,ri)=>state.rbacResources.forEach(resource=>{const p=role.permissions[resource]||{read:false,write:false,approve:false};rows.push(`<tr data-rbac-role="${esc(role.name)}" data-rbac-resource="${esc(resource)}"><td><strong>${esc(role.name)}</strong><br><span class="muted">${esc(role.scope)}</span></td><td>${esc(resource)}</td><td><button class="permission-chip read ${p.read?'on':''}" data-action="toggle-rbac-v6" data-role="${ri}" data-resource="${esc(resource)}" data-mode="read">Read</button></td><td><button class="permission-chip write ${p.write?'on':''}" data-action="toggle-rbac-v6" data-role="${ri}" data-resource="${esc(resource)}" data-mode="write">Write</button></td><td><button class="permission-chip approve ${p.approve?'on':''}" data-action="toggle-rbac-v6" data-role="${ri}" data-resource="${esc(resource)}" data-mode="approve">Approve</button></td><td>${smallAction('Scope','edit-permission-scope-v5',`${ri}|${resource}`)}</td></tr>`)}));
      content=`<div class="notice" style="margin-bottom:14px"><span class="kpi-icon">${icon('settings')}</span><div><strong>Read, write and approve are separate permissions</strong><p>Write and approve require read access. Approval authority is additionally constrained by workflow type, amount, entity scope, SoD and eSignature policy.</p></div></div><div class="rbac-toolbar"><div class="left"><input id="rbacSearchV6" placeholder="Search roles or resources"><select id="rbacRoleFilterV6"><option>All roles</option>${state.rbacV5.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select><select id="rbacResourceFilterV6"><option>All resources</option>${state.rbacResources.map(r=>`<option>${esc(r)}</option>`).join('')}</select></div><div class="right">${actionV6('New access request','new-access-request-v5','','','plus')}${actionV6('Add role','add-role-v6','','','plus')}${actionV6('Save RBAC','save-rbac-v6','','primary')}</div></div><div class="rbac-summary-v6">${roleCards}</div><div class="table-wrap"><table><thead><tr><th>Role</th><th>Resource</th><th>Read</th><th>Write</th><th>Approve</th><th>Scope</th></tr></thead><tbody id="rbacMatrixV6">${rows.join('')}</tbody></table></div>`;
    }
    if(state.settingsTabV6==='users'){
      const rows=state.rbacUsersV6.map(u=>`<tr><td><div class="rbac-user-v6">${u.photo?`<img src="${u.photo}" alt="${esc(u.name)}">`:`<span class="avatar" style="width:34px;height:34px;border-radius:10px">${esc(u.name.split(' ').map(x=>x[0]).join(''))}</span>`}<span><strong>${esc(u.name)}</strong><span>${esc(u.email)}</span></span></div></td><td>${esc(u.role)}</td><td>${esc(u.scope)}</td><td>${status(u.status)}</td><td>${esc(u.lastAccess)}</td><td><div class="actions">${smallAction('Edit assignment','edit-user-assignment-v6',u.id)}${smallAction('Request access','new-access-request-v5',u.role)}${smallAction('Review access','review-user-access-v6',u.id)}</div></td></tr>`);
      content=`<div class="rbac-toolbar"><div class="left"><input placeholder="Search users, groups or email"><select><option>All roles</option>${state.rbacV5.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select><select><option>All scopes</option><option>Group Consolidated</option><option>Assigned entity</option></select></div><div class="right">${actionV6('Add user assignment','add-user-assignment-v6','','primary','plus')}${actionV6('Import identity groups','import-idp-groups-v6')}</div></div>${card('Users and assignments','Identity-provider users, roles, entity scope, access expiry and last access.',table(['User','Role','Scope','Status','Last access','Actions'],rows))}`;
    }
    if(state.settingsTabV6==='requests'){
      content=`<div class="layer-toolbar"><div><h3 style="margin:0">Access requests</h3><p class="muted">Users request read, write or approve access. The responsible owner and Group Administrator review SoD, scope, duration and business need.</p></div>${actionV6('Create request','new-access-request-v5','','primary','plus')}</div><div class="access-request-grid">${state.accessRequests.map(r=>`<article class="access-request"><div class="request-head"><div><h4>${esc(r.user)}</h4><p>${esc(r.role)} | ${esc(r.requested)}</p></div>${status(r.status)}</div><div class="request-facts"><div><span>Resource</span><strong>${esc(r.resource)}</strong></div><div><span>Access</span><strong>${esc(r.access)}</strong></div><div><span>Scope</span><strong>${esc(r.scope)}</strong></div><div><span>Request ID</span><strong>${esc(r.id)}</strong></div></div><p><strong>Reason:</strong> ${esc(r.reason)}</p><div class="actions">${smallAction('Preview','preview-access-request-v5',r.id,'eye')}${r.status==='Pending'?smallAction('Approve','approve-access-v5',r.id)+smallAction('Deny','deny-access-v5',r.id):''}</div></article>`).join('')}</div>`;
    }
    if(state.settingsTabV6==='approvers'){
      const rows=state.rbacV5.filter(r=>r.approvalTypes?.length).map((r,ri)=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.approvalTypes.map(x=>`<span class="rbac-badge-v6">${esc(x)}</span>`).join(' ')}</td><td>${r.approvalLimit===Infinity?'Unlimited':money(r.approvalLimit||0)}</td><td>${esc(r.scope)}</td><td>${r.canDelegate?'Yes':'No'}</td><td>${esc(r.mfa||'Required')}</td><td>${smallAction('Edit authority','edit-approver-v6',r.name)}</td></tr>`);
      content=`<div class="notice" style="margin-bottom:14px"><span class="kpi-icon">${icon('approve')}</span><div><strong>Approver RBAC</strong><p>Approval is not implied by write access. Each approver requires an approval permission, workflow type, amount limit, entity scope and active delegation or assignment.</p></div></div>${card('Approver authority register','CEO, CFO, department and administrative decision authority.',table(['Role','Approval types','Limit','Scope','Delegation','MFA / eSign',''],rows),actionV6('Add approver rule','add-approver-v6','','primary','plus'))}`;
    }
    if(state.settingsTabV6==='sod'){
      content=`<div class="grid two"><section class="card"><div class="card-head"><div><h3>Segregation-of-duties rules</h3><p>Hard blocks and monitored conflicts.</p></div>${actionV6('Add rule','add-sod-rule-v6','','','plus')}</div><div class="card-body list"><div class="list-row"><div class="list-main"><strong>Requester cannot approve own requisition</strong><span>Hard block | All entities</span></div>${status('Active')}</div><div class="list-row"><div class="list-main"><strong>Evaluator cannot approve final award where conflict declared</strong><span>Hard block | Tenders</span></div>${status('Active')}</div><div class="list-row"><div class="list-main"><strong>Group Administrator cannot select commercial winner</strong><span>Hard block | Award decisions</span></div>${status('Active')}</div><div class="list-row"><div class="list-main"><strong>Vendor bank change requires maker-checker</strong><span>Hard block | Vendor master</span></div>${status('Active')}</div></div></section><section class="card"><div class="card-head"><div><h3>Emergency and privileged access</h3><p>Time-bound break-glass access with review.</p></div>${actionV6('Request emergency access','new-access-request-v5','Group Administrator','','plus')}</div><div class="card-body list"><div class="list-row"><div class="list-main"><strong>Privileged sessions</strong><span>2 active | Full command audit enabled</span></div>${status('Monitored')}</div><div class="list-row"><div class="list-main"><strong>Quarterly access certification</strong><span>Due 15 Aug 2026</span></div>${status('Due')}</div><div class="list-row"><div class="list-main"><strong>Dormant access</strong><span>3 assignments inactive for 90+ days</span></div>${status('Review')}</div></div></section></div>`;
    }
    if(state.settingsTabV6==='integrations'){
      content=`<div class="grid three">${[['Accounting API','Journals, AP, tax and fixed assets','account'],['Vendor Email and Portal','Requests, reminders, inbound documents and messages','mail'],['Identity Provider','Users, groups, MFA and role assignments','settings'],['eSignature Service','OTP, signing fields, certificates and reminders','signature'],['Document Vault','Versioned files, templates and audit evidence','document'],['OCR and AI Match','Invoice extraction and exception signals','invoice']].map(x=>`<article class="card"><div class="card-body" style="padding-top:16px"><span class="kpi-icon">${icon(x[2])}</span><h3>${x[0]}</h3><p class="muted">${x[1]}</p><div class="actions">${smallAction('Configure','configure-integration-v5',x[0])}${smallAction('Test','test-integration',x[0])}</div></div></article>`).join('')}</div>`;
    }
    return `<div class="page">${pageHead('Administration','Configuration, RBAC and Access','Robust role, user, approver, access-request, SoD and integration administration with separate read, write and approve rights.',actionV6('Export configuration','export-config','','','download'))}<div class="grid kpis">${kpi('Roles',state.rbacV5.length,'Including CEO, CFO and Group Administrator','settings')}${kpi('Assigned users',state.rbacUsersV6.length,'Named users and identity groups','vendor')}${kpi('Pending access requests',state.accessRequests.filter(r=>r.status==='Pending').length,'Owner and administrator review','approve')}${kpi('Approver roles',state.rbacV5.filter(r=>r.approvalTypes?.length).length,'Workflow and value limits','approve')}${kpi('SoD rules','12','Four hard-block categories','audit')}${kpi('Privileged roles',3,'CEO, CFO and Group Administrator','settings')}</div><section class="card">${tabbar}<div class="settings-pane">${content}</div></section></div>`;
  }

