    openV6Modal('Review and sign',`${env.id} | ${env.document}`,`<div class="grid two"><section><div class="notice"><span class="kpi-icon">${icon('signature')}</span><div><strong>Authenticated as Nyasha Moyo</strong><p>SSO + MFA verified. Your name, role, timestamp and IP evidence will be included in the signing certificate.</p></div></div><div style="height:14px"></div>${paperV6(docByIdV6(env.document.split(' ')[0]),false)}</section><section class="card"><div class="card-head"><div><h3>Electronic signature</h3><p>Type or draw your signature, then confirm consent.</p></div></div><div class="card-body"><div class="field"><label>Typed legal name</label><input id="typedSignatureV6" value="Nyasha Moyo"></div><div class="signature-preview-v6" id="signaturePreviewV6">Nyasha Moyo</div><div class="field" style="margin-top:14px"><label>Draw signature</label><canvas id="signatureCanvasV6" class="signature-canvas-v6"></canvas></div><div class="actions" style="margin:8px 0 14px">${smallAction('Clear drawing','clear-signature-v6')}</div><label style="display:flex;gap:8px;align-items:flex-start;font-size:11px"><input id="signatureConsentV6" type="checkbox"> I have reviewed the document and consent to use this electronic signature as my binding signature for this controlled procurement record.</label><div class="field" style="margin-top:14px"><label>Signing comment</label><textarea id="signatureCommentV6">Reviewed and approved within delegated authority.</textarea></div></div></section></div>`,actionV6('Decline','esign-decline-v6',env.id,'danger')+actionV6('Apply signature','esign-confirm-v6',env.id,'primary','signature'),'full');
    setTimeout(initSignatureCanvasV6,0);
