  function initSignatureCanvasV6(){
    const c=$('#signatureCanvasV6');if(!c)return;const rect=c.getBoundingClientRect();c.width=Math.max(600,Math.floor(rect.width*2));c.height=340;const ctx=c.getContext('2d');ctx.scale(2,2);ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#000000';let drawing=false;
    const pos=e=>{const r=c.getBoundingClientRect();const p=e.touches?.[0]||e;return {x:p.clientX-r.left,y:p.clientY-r.top}};
    const start=e=>{drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()};const move=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()};const end=()=>drawing=false;
    c.addEventListener('pointerdown',start);c.addEventListener('pointermove',move);c.addEventListener('pointerup',end);c.addEventListener('pointerleave',end);
  }

