    'settings-tab-v6':a=>{state.settingsTabV6=a.dataset.id;render()},
    'toggle-rbac-v6':a=>{
      const [roleName,resource,level]=a.dataset.id.split('|');const role=state.rbacV5.find(x=>x.name===roleName);if(!role)return;role.permissions[resource]??={read:false,write:false,approve:false};const p=role.permissions[resource];p[level]=!p[level];if(level==='read'&&!p.read){p.write=false;p.approve=false}if((level==='write'||level==='approve')&&p[level])p.read=true;render()
    },
    'save-rbac-v6':()=>toast('RBAC configuration saved','Read, write and approve rights were versioned and applied to future sessions.'),
    'edit-role-v6':a=>editRoleV6(a.dataset.id),
    'new-role-v6':()=>editRoleV6('Procurement Officer'),
    'save-role-v6':a=>{const f=$('#roleEditFormV6');if(!f?.reportValidity())return;const d=new FormData(f);const r=state.rbacV5.find(x=>x.name===d.get('original'));if(r){r.name=d.get('name');r.scope=d.get('scope');r.description=d.get('description');r.approvalLimit=d.get('limit')===''?Infinity:Number(d.get('limit'));r.approvalTypes=String(d.get('types')||'').split(',').map(x=>x.trim()).filter(Boolean);r.mfa=d.get('mfa');r.canDelegate=!!d.get('delegate')}closeOverlay();render();toast('Role updated','Role permissions, approval authority and security controls were saved.')},
    'duplicate-role-v6':a=>{const r=state.rbacV5.find(x=>x.name===a.dataset.id);if(r)state.rbacV5.push({...r,name:`${r.name} Copy`,permissions:JSON.parse(JSON.stringify(r.permissions))});closeOverlay();render();toast('Role duplicated','Review the copied permissions and scope before assigning users.')},
