    'edit-user-assignment-v6':a=>assignUserV6(a.dataset.id),
    'save-user-assignment-v6':()=>{const f=$('#userAssignmentFormV6');if(!f?.reportValidity())return;const d=new FormData(f);let u=state.rbacUsersV6.find(x=>x.id===d.get('id'));if(!u){u={id:'USR-'+String(state.rbacUsersV6.length+1).padStart(3,'0'),status:'Active',lastAccess:'Never'};state.rbacUsersV6.push(u)}u.name=d.get('name');u.email=d.get('email');u.role=d.get('role');u.scope=d.get('scope');closeOverlay();render();toast('User assignment saved','The assignment will be enforced after the next authentication refresh.')},
