    'open-esign-envelope-v6':a=>esignEnvelopeV6(a.dataset.id),
    'preview-esign-envelope-v6':a=>previewDocV6(a.dataset.id),
    'send-esign-envelope-v6':a=>{const f=$('#esignBuilderFormV6');if(!f?.reportValidity())return;const d=new FormData(f);const id='ENV-'+String(183+state.signatureEnvelopesV6.length).padStart(5,'0');state.signatureEnvelopesV6.unshift({id,document:d.get('document'),status:'Awaiting signer 1',order:d.get('order'),signers:[{name:String(d.get('signer1')).split(' · ')[0],role:String(d.get('signer1')).split(' · ')[1]||'Signer',status:'Pending',date:'Due now'},{name:String(d.get('signer2')).split(' · ')[0],role:String(d.get('signer2')).split(' · ')[1]||'Signer',status:'Queued',date:'After signer 1'},{name:String(d.get('signer3')).split(' · ')[0],role:'External signer',status:'Queued',date:'After signer 2'}],due:fmtDateV6(d.get('due')),reminder:d.get('reminder')});closeOverlay();render();toast('eSignature envelope sent',`${id} was sent with ordered signers, authentication and reminders.`)},
    'esign-sign-v6':a=>esignSignV6(a.dataset.id),
    'signature-mode-v6':a=>{const draw=a.dataset.id==='draw';$('#signatureDrawV6').hidden=!draw;$('#signatureTypeV6').hidden=draw;document.querySelectorAll('[data-action="signature-mode-v6"]').forEach(b=>b.classList.toggle('active',b===a));if(draw)initSignatureCanvasV6()},
    'clear-signature-v6':()=>{const c=$('#signatureCanvasV6');c?.getContext('2d').clearRect(0,0,c.width,c.height)},
    'apply-signature-v6':a=>{if(!$('#signatureConsentV6')?.checked){toast('Consent required','Confirm electronic-signature consent before signing.','warning');return}const p=state.approvalPromptsV6.find(x=>x.id===a.dataset.id);if(p)p.status='Approved';const e=state.signatureEnvelopesV6.find(x=>x.id===a.dataset.id);if(e){const pending=e.signers.find(x=>x.status==='Pending');if(pending){pending.status='Signed';pending.date='01 Aug 2026 06:38'}const next=e.signers.find(x=>x.status==='Queued');if(next)next.status='Pending';e.status=next?`Awaiting ${next.role}`:'Completed'}closeOverlay();render();toast('Document signed','The signature, consent, authentication, timestamp and document hash were recorded.')},
    'esign-reminder-v6':a=>toast('Reminder sent',`${a.dataset.id} signers received a secure reminder.`),

    'confirm-bid-winner-v6':a=>{const selected=document.querySelector('[name="awardWinnerV6"]:checked');if(!selected){toast('Select a bidder','Choose the winning bidder before recording the decision.','warning');return}const rationale=$('#awardRationaleV6')?.value||'';openV6Modal('Confirm Winning Bidder',`${a.dataset.id} | Final authorised-user decision`, `<div class="notice"><span class="kpi-icon">${icon('approve')}</span><div><strong>${esc(selected.value)}</strong><p>The system recommendation is advisory. You are confirming the final user decision and sending it into the configured approval workflow.</p></div></div><div class="source-meta" style="margin-top:14px"><div><span>Tender</span><strong>${esc(a.dataset.id)}</strong></div><div><span>Conflict</span><strong>${esc($('#awardConflictV6')?.value||'No conflict')}</strong></div></div><h4>Decision rationale</h4><p>${esc(rationale)}</p>`,actionV6('Go back','close-modal-v6')+actionV6('Confirm and route','save-bid-winner-v6',`${a.dataset.id}|${selected.value}`,'primary','approve'),'wide')},
    'save-bid-winner-v6':a=>{const [tid,vendor]=a.dataset.id.split('|');state.bidAwardsV6[tid]=vendor;const t=state.tenders.find(x=>x.id===tid);if(t)t.stage='Award approval';state.approvalPromptsV6.unshift({id:'APR-'+Date.now(),type:'Tender award',record:tid,title:`Award ${t?.title||tid} to ${vendor}`,entity:t?.entity||'Group',amount:t?.value||0,role:'CEO',approver:'Tendai Moyo',due:'Today',priority:'High',status:'Awaiting me',esign:true,reason:'Final user-selected bid award approval'});closeOverlay();render();toast('Winning bidder recorded',`${vendor} was selected by the authorised user. CFO and CEO approval prompts were issued.`)},
    'preview-award-report-v6':a=>previewDocV6({id:a.dataset.id,name:`${a.dataset.id} Bid Evaluation and Award Report`,version:'Draft',status:'Decision required',owner:'Evaluation Committee',content:`<h1>Bid Evaluation and Award Report</h1><p><strong>Tender:</strong> ${esc(a.dataset.id)}</p><h2>Evaluation outcome</h2><p>The evaluation committee applied the approved technical, commercial, delivery and support criteria. Scores are advisory and support, but do not replace, the authorised user's final award decision.</p><h2>Recommendation</h2><p>TechNova Solutions achieved the highest weighted score. The authorised decision-maker may accept or reject the recommendation after considering value, risk, conflicts, policy compliance and the procurement objective.</p><h2>Approvals</h2><p>The final award is subject to the configured CFO and CEO approval workflow and electronic signatures.</p>`}),

