  /* Unified compliance object used consistently by reminders, documents, POs, contracts and invoices. */
  taxRuleV6=function(vendorOrName){
    const vendor=typeof vendorOrName==='string'?state.vendors.find(v=>v.name===vendorOrName):vendorOrName;
    if(!vendor){return {state:'pending',days:null,level:'warning',title:'Vendor not selected',label:'Vendor not selected',detail:'Select an approved vendor to calculate the configured purchase tax rule.',rule:'Select an approved vendor to calculate the configured purchase tax rule.',withholding:0,status:'Pending',poClause:'Vendor compliance and tax treatment must be validated before issue.',contractClause:'Vendor compliance and tax treatment must be validated before execution.'}}
    if(vendor.country!=='Zimbabwe'){
      const detail='Route the purchase to Finance for import VAT, customs and non-resident tax review before the contract or purchase order is approved.';
      return {state:'special',days:null,level:'warning',title:'Non-resident tax review',label:'Non-resident tax review',detail,rule:detail,withholding:0,status:'Specialist review',poClause:detail,contractClause:`The Supplier is a non-resident vendor. Applicable import taxes, customs, VAT and non-resident withholding treatment shall be confirmed by Finance before payment. ${detail}`};
    }
    const days=vendor.taxExpiry?daysUntilV6(vendor.taxExpiry):null;
    if(!vendor.taxExpiry){
      const detail='No approved ITF263 tax clearance is recorded. Apply the configured 30% withholding control and route the document for compliance review.';
      return {state:'missing',days:null,level:'blocked',title:'Tax clearance missing',label:'30% withholding configured',detail,rule:detail,withholding:30,status:'Missing',poClause:'The Supplier has no approved current ITF263 tax clearance on record. The Purchaser shall apply the configured 30% withholding treatment until valid clearance is received and approved.',contractClause:'The Supplier shall maintain valid tax clearance throughout the contract. While no approved ITF263 is held, the Purchaser shall apply the configured 30% withholding treatment and may suspend payment pending compliance review.'};
    }
    if(days<0){
      const detail=`The recorded ITF263 tax clearance expired ${Math.abs(days)} day(s) ago. Apply the configured 30% withholding control until a replacement is approved.`;
      return {state:'expired',days,level:'blocked',title:'Tax clearance expired',label:'30% withholding configured',detail,rule:detail,withholding:30,status:'Expired',poClause:'The Supplier tax clearance has expired. The Purchaser shall apply the configured 30% withholding treatment and require an approved replacement certificate.',contractClause:'The Supplier tax clearance has expired. The Purchaser shall apply the configured 30% withholding treatment, issue compliance reminders and may withhold or suspend affected payments until a valid certificate is approved.'};
    }
    if(days<=60){
      const detail=`Tax clearance expires in ${days} day(s). Continue only within current approval while automated reminders are sent to the vendor, Procurement, Finance and Group Administration.`;
      return {state:'expiring',days,level:'warning',title:'Tax clearance expiring',label:'Tax clearance expiring',detail,rule:detail,withholding:0,status:'Expiring',poClause:`The Supplier tax clearance remains valid but expires in ${days} day(s). The Supplier must submit a replacement before expiry. Tax treatment will be recalculated at invoice and payment review.`,contractClause:`The Supplier shall provide renewed tax clearance before the current certificate expires in ${days} day(s). Failure to maintain approved clearance will trigger the configured withholding and compliance controls.`};
    }
    const detail='Approved ITF263 tax clearance is current. Apply the standard VAT and withholding controls configured for the purchase and invoice.';
    return {state:'valid',days,level:'',title:'Tax clearance current',label:'Standard compliant treatment',detail,rule:detail,withholding:0,status:'Valid',poClause:'The Supplier has approved current tax clearance. Standard configured VAT and withholding controls apply, subject to revalidation at invoice and payment stages.',contractClause:'The Supplier shall maintain current tax clearance and statutory compliance throughout the contract. The Purchaser may recalculate tax treatment if the compliance status changes.'};
  };

