    const role=state.rbacV5.find(x=>x.name===roleName);if(!role||!resource||!level)return;
    role.permissions[resource]??={read:false,write:false,approve:false};const p=role.permissions[resource];p[level]=!p[level];
    if(level==='read'&&!p.read){p.write=false;p.approve=false}
    if((level==='write'||level==='approve')&&p[level])p.read=true;
    render();
