  const escV20=value=>String(value??'').replace(/[&<>'"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
  const auditSeedV20={
    'AUD-88291':{activity:'Vendor bank account changed',record:'VEN-00482 · TechNova Solutions',actor:'S. Chikowore',timestamp:'01 Aug 2026 05:11',classification:'High priority',source:'Vendor master service',reason:'Authorised bank-detail amendment after maker-checker validation.',previous:'Bank account ending 1842',next:'Bank account ending 7631'},
    'AUD-88290':{activity:'Tender bid envelope opened',record:'TN-2026-013 · Committee session',actor:'Committee 03',timestamp:'01 Aug 2026 04:46',classification:'Controlled',source:'Tender opening service',reason:'Scheduled bid-opening session reached the authorised opening time.',previous:'Envelope sealed',next:'Envelope opened for authorised committee'},
    'AUD-88289':{activity:'Invoice payment blocked',record:'INV-98430 · 2.4% price variance',actor:'AI Match Engine',timestamp:'01 Aug 2026 04:31',classification:'Exception',source:'Three-way match engine',reason:'Invoice price exceeded the approved purchase-order price tolerance.',previous:'Payment validation pending',next:'Payment blocked · exception assigned'},
    'AUD-88288':{activity:'Procurement plan version submitted',record:'PLAN-26-GRP · v1.4',actor:'T. Moyo',timestamp:'31 Jul 2026 16:04',classification:'Workflow',source:'Annual planning workflow',reason:'Updated consolidated plan submitted to the configured approval route.',previous:'Draft v1.3',next:'Submitted v1.4'},
    'AUD-88287':{activity:'Fixed asset journal generated',record:'GRN-2026-0219 · MRI Scanner',actor:'P2P Accounting API',timestamp:'31 Jul 2026 15:46',classification:'System',source:'Accounting integration',reason:'Accepted fixed-asset GRN transferred to the accounting and fixed-asset registries.',previous:'Asset transfer pending',next:'Journal generated · registry record proposed'}
  };
